import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import {
  FaStar,
  FaRegStar,
  FaComment,
  FaUser,
  FaCalendarAlt,
  FaGraduationCap,
  FaLanguage,
} from "react-icons/fa";
import {
  MdComputer,
  MdAccountBalance,
  MdEngineering,
  MdCalculate,
} from "react-icons/md";

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [featuredCourses, setFeaturedCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (location.state?.message) {
      alert(location.state.message);
      navigate(location.pathname, { replace: true, state: {} });
    }

    const fetchData = async () => {
      try {
        const [cursosRes, featuredRes, comentariosRes] = await Promise.all([
          axios.get("http://localhost:5000/cursos"),
          axios.get("http://localhost:5000/cursos?destaque=true"),
          axios.get("http://localhost:5000/comentarios"),
        ]);

        setCursos(cursosRes.data);
        setFeaturedCourses(featuredRes.data.slice(0, 3));
        setComentarios(comentariosRes.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    const checkAuth = () => {
      const token = localStorage.getItem("token");
      const userData = JSON.parse(localStorage.getItem("user"));
      if (token && userData) {
        setIsAuthenticated(true);
        setUser(userData);
        setNome(userData.nome || "");
        setEmail(userData.email || "");
      }
    };

    fetchData();
    checkAuth();
  }, [navigate, location]);

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", {
        state: {
          from: path,
          message: "Por favor, faça login para acessar esta página",
        },
      });
    }
  };

  const handleComentarioClick = () => {
    setShowComentarioModal(true);
  };

  const handleSubmitComentario = async () => {
    if (!novoComentario.trim()) {
      alert("Por favor, escreva um comentário antes de enviar.");
      return;
    }

    if (!isAuthenticated && (!nome.trim() || !email.trim())) {
      alert("Por favor, preencha seu nome e e-mail.");
      return;
    }

    try {
      const comentarioData = {
        conteudo: novoComentario,
        nome,
        email,
      };

      const response = await axios.post(
        "http://localhost:5000/comentarios",
        comentarioData
      );

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      if (!isAuthenticated) {
        setNome("");
        setEmail("");
      }
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      alert("Erro ao enviar comentário. Por favor, tente novamente.");
    }
  };

  // Ordenar os cursos por área
  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  // Ordenar os cursos dentro de cada área por nome
  Object.keys(cursosPorArea).forEach((area) => {
    cursosPorArea[area].sort((a, b) => a.nome.localeCompare(b.nome));
  });

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5 py-5">
        <div
          className="spinner-border text-primary"
          role="status"
          style={{ width: "3rem", height: "3rem" }}
        >
          <span className="visually-hidden">Carregando...</span>
        </div>
        <p className="mt-3">Carregando conteúdo...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5 py-5">
        <div
          className="alert alert-danger"
          style={{ maxWidth: "600px", margin: "0 auto" }}
        >
          <h5>Erro ao carregar conteúdo</h5>
          <p>{error}</p>
          <button
            className="btn btn-outline-danger"
            onClick={() => window.location.reload()}
          >
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="home-page" style={{ backgroundColor: "#f8f9fa" }}>
      {/* Hero Section */}
      <div
        className="hero-section text-center py-5"
        style={{
          background: "linear-gradient(135deg, #3498db, #2c3e50)",
          color: "white",
          marginBottom: "40px",
          padding: "80px 20px",
          borderRadius: "0 0 20px 20px",
          boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
        }}
      >
        <h1 className="display-4 fw-bold mb-3">Bem-vindo ao EducaWeb</h1>
        <p
          className="lead mb-4"
          style={{
            maxWidth: "700px",
            margin: "0 auto",
            fontSize: "1.25rem",
          }}
        >
          Transforme sua carreira com nossos cursos online de alta qualidade
          ministrados por especialistas
        </p>
        <div className="d-flex justify-content-center gap-3 mt-4">
          <button
            className="btn btn-light btn-lg px-4"
            onClick={() => handleProtectedLink("/cursos")}
            style={{
              borderRadius: "30px",
              fontWeight: "500",
              transition: "all 0.3s",
            }}
          >
            Explorar Cursos
          </button>
          {!isAuthenticated && (
            <button
              className="btn btn-outline-light btn-lg px-4"
              onClick={() => navigate("/register")}
              style={{
                borderRadius: "30px",
                fontWeight: "500",
                transition: "all 0.3s",
              }}
            >
              Cadastre-se Grátis
            </button>
          )}
        </div>
      </div>

      {/* Cursos em Destaque */}
      {featuredCourses.length > 0 && (
        <div className="container mb-5">
          <h2
            className="text-center mb-5"
            style={{
              color: "#2c3e50",
              position: "relative",
              paddingBottom: "15px",
            }}
          >
            <span
              style={{
                backgroundColor: "#f8f9fa",
                padding: "0 20px",
                position: "relative",
                zIndex: 1,
              }}
            >
              Cursos em Destaque
            </span>
            <span
              style={{
                position: "absolute",
                top: "50%",
                left: 0,
                right: 0,
                height: "2px",
                backgroundColor: "#e9ecef",
                zIndex: 0,
              }}
            ></span>
          </h2>

          <div className="row g-4">
            {featuredCourses.map((curso) => (
              <div className="col-md-4" key={`featured-${curso.id}`}>
                <div
                  className="card h-100 border-0 shadow-sm-hover"
                  style={{
                    transition: "transform 0.3s, box-shadow 0.3s",
                    borderRadius: "15px",
                    overflow: "hidden",
                    cursor: "pointer",
                    border: "1px solid rgba(0,0,0,0.05)",
                  }}
                  onClick={() => handleProtectedLink(`/curso/${curso.id}`)}
                >
                  <div
                    style={{
                      height: "160px",
                      background: `linear-gradient(45deg, #${Math.floor(
                        Math.random() * 16777215
                      ).toString(16)}, #${Math.floor(
                        Math.random() * 16777215
                      ).toString(16)})`,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      color: "white",
                      fontSize: "24px",
                    }}
                  >
                    {getAreaIcon(curso.area)}
                  </div>
                  <div className="card-body">
                    <div className="d-flex justify-content-between align-items-center mb-2">
                      <span
                        className="badge bg-primary"
                        style={{
                          borderRadius: "10px",
                          backgroundColor: "#3498db !important",
                        }}
                      >
                        {formatAreaName(curso.area)}
                      </span>
                      <div className="text-warning">
                        {[...Array(5)].map((_, i) =>
                          i < 4 ? <FaStar key={i} /> : <FaRegStar key={i} />
                        )}
                      </div>
                    </div>
                    <h5 className="card-title" style={{ minHeight: "48px" }}>
                      {curso.nome}
                    </h5>
                    <p
                      className="card-text text-muted small"
                      style={{
                        minHeight: "60px",
                        display: "-webkit-box",
                        WebkitLineClamp: 3,
                        WebkitBoxOrient: "vertical",
                        overflow: "hidden",
                      }}
                    >
                      {curso.descricao ||
                        "Curso de alta qualidade na área de " +
                          formatAreaName(curso.area)}
                    </p>
                  </div>
                  <div className="card-footer bg-white border-0 d-flex justify-content-between align-items-center">
                    <small className="text-muted">
                      <FaCalendarAlt className="me-1" />
                      {formatDate(curso.dataInicio)}
                    </small>
                    <span className="badge bg-light text-dark">
                      {curso.nivel}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Áreas de Conhecimento */}
      <div className="container mb-5">
        <h2
          className="text-center mb-5"
          style={{
            color: "#2c3e50",
            position: "relative",
            paddingBottom: "15px",
          }}
        >
          <span
            style={{
              backgroundColor: "#f8f9fa",
              padding: "0 20px",
              position: "relative",
              zIndex: 1,
            }}
          >
            Nossas Áreas de Conhecimento
          </span>
          <span
            style={{
              position: "absolute",
              top: "50%",
              left: 0,
              right: 0,
              height: "2px",
              backgroundColor: "#e9ecef",
              zIndex: 0,
            }}
          ></span>
        </h2>

        <div className="row g-4">
          {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
            <div className="col-md-6" key={area}>
              <div
                className="card h-100 border-0 shadow-sm"
                style={{
                  borderRadius: "15px",
                  transition: "transform 0.3s",
                  ":hover": {
                    transform: "translateY(-5px)",
                  },
                }}
              >
                <div className="card-body">
                  <div className="d-flex align-items-center mb-3">
                    <div
                      className="me-3"
                      style={{
                        width: "50px",
                        height: "50px",
                        borderRadius: "50%",
                        backgroundColor: "#e3f2fd",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: "#3498db",
                        fontSize: "20px",
                      }}
                    >
                      {getAreaIcon(area)}
                    </div>
                    <h3 className="h4 mb-0" style={{ color: "#3498db" }}>
                      {formatAreaName(area)}
                    </h3>
                  </div>

                  <ul className="list-group list-group-flush">
                    {cursosDaArea.map((curso) => (
                      <li
                        className="list-group-item border-0 px-0 py-2 d-flex justify-content-between align-items-center"
                        key={curso.id}
                        style={{
                          borderBottom: "1px solid rgba(0,0,0,0.05)",
                          transition: "background-color 0.2s",
                          ":hover": {
                            backgroundColor: "rgba(52, 152, 219, 0.05)",
                          },
                        }}
                        onClick={() =>
                          handleProtectedLink(`/curso/${curso.id}`)
                        }
                      >
                        <div style={{ flex: 1 }}>
                          <strong>{curso.nome}</strong>
                          <div className="d-flex gap-3 mt-1">
                            <small className="text-muted">
                              <FaUser className="me-1" />
                              {curso.periodo}
                            </small>
                            <small className="text-muted">
                              <FaGraduationCap className="me-1" />
                              Nível {curso.nivel}
                            </small>
                          </div>
                        </div>
                        <button
                          className="btn btn-sm btn-outline-primary"
                          style={{
                            borderRadius: "20px",
                            fontSize: "12px",
                            padding: "3px 12px",
                          }}
                        >
                          Ver
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Testemunhos */}
      <div
        className="testimonials-section py-5"
        style={{
          backgroundColor: "#2c3e50",
          color: "white",
          marginTop: "40px",
        }}
      >
        <div className="container">
          <h2 className="text-center mb-5">O que dizem nossos alunos</h2>

          <div className="row g-4">
            {comentarios.length > 0 ? (
              comentarios.slice(0, 3).map((comentario) => (
                <div className="col-md-4" key={comentario.id}>
                  <div
                    className="h-100 p-4 rounded"
                    style={{
                      backgroundColor: "rgba(255,255,255,0.1)",
                      borderLeft: "4px solid #3498db",
                      height: "100%",
                      transition: "transform 0.3s",
                      ":hover": {
                        transform: "translateY(-5px)",
                      },
                    }}
                  >
                    <div className="d-flex align-items-center mb-3">
                      <div
                        className="me-3"
                        style={{
                          width: "50px",
                          height: "50px",
                          borderRadius: "50%",
                          backgroundColor: "#3498db",
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          color: "white",
                          fontSize: "20px",
                          fontWeight: "bold",
                        }}
                      >
                        {comentario.nome.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <h5 className="mb-0">{comentario.nome}</h5>
                        <small className="text-white-50">
                          Aluno{" "}
                          {formatAreaName(
                            comentario.area || "Ciências da Computação"
                          )}
                        </small>
                      </div>
                    </div>
                    <p className="mb-3" style={{ fontStyle: "italic" }}>
                      "{comentario.conteudo}"
                    </p>
                    <small className="text-white-50 d-flex align-items-center">
                      <FaCalendarAlt className="me-2" />
                      {new Date(comentario.dataPublicacao).toLocaleDateString(
                        "pt-PT",
                        {
                          day: "2-digit",
                          month: "long",
                          year: "numeric",
                        }
                      )}
                    </small>
                  </div>
                </div>
              ))
            ) : (
              <div className="col-12 text-center py-4">
                <div
                  className="p-4 rounded"
                  style={{ backgroundColor: "rgba(255,255,255,0.1)" }}
                >
                  <p className="text-white-50 mb-0">
                    Nenhum comentário ainda.{" "}
                    {isAuthenticated
                      ? "Seja o primeiro a comentar!"
                      : "Faça login para compartilhar sua experiência."}
                  </p>
                </div>
              </div>
            )}
          </div>

          {isAuthenticated && (
            <div className="text-center mt-5">
              <button
                className="btn btn-outline-light"
                onClick={handleComentarioClick}
                style={{
                  padding: "10px 30px",
                  borderRadius: "30px",
                  fontWeight: "500",
                  borderWidth: "2px",
                  transition: "all 0.3s",
                  ":hover": {
                    backgroundColor: "rgba(255,255,255,0.1)",
                  },
                }}
              >
                <FaComment className="me-2" />
                Deixar seu testemunho
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Modal de Comentário */}
      {showComentarioModal && (
        <div
          className="modal"
          style={{
            display: "block",
            backgroundColor: "rgba(0,0,0,0.5)",
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 1050,
          }}
        >
          <div className="modal-dialog modal-dialog-centered">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Deixe seu Comentário</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowComentarioModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                <div className="mb-3">
                  <label htmlFor="nome" className="form-label">
                    Seu Nome
                  </label>
                  <input
                    type="text"
                    className="form-control"
                    id="nome"
                    value={nome}
                    onChange={(e) =>
                      !isAuthenticated && setNome(e.target.value)
                    }
                    placeholder="Digite seu nome"
                    readOnly={isAuthenticated}
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="email" className="form-label">
                    Seu E-mail
                  </label>
                  <input
                    type="email"
                    className="form-control"
                    id="email"
                    value={email}
                    onChange={(e) =>
                      !isAuthenticated && setEmail(e.target.value)
                    }
                    placeholder="Digite seu e-mail"
                    readOnly={isAuthenticated}
                  />
                </div>
                <div className="mb-3">
                  <label htmlFor="comentario" className="form-label">
                    Comentário
                  </label>
                  <textarea
                    className="form-control"
                    id="comentario"
                    rows="4"
                    value={novoComentario}
                    onChange={(e) => setNovoComentario(e.target.value)}
                    placeholder="Escreva seu comentário aqui..."
                    required
                  ></textarea>
                </div>
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowComentarioModal(false)}
                  style={{ borderRadius: "20px" }}
                >
                  Cancelar
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleSubmitComentario}
                  disabled={!novoComentario.trim()}
                  style={{ borderRadius: "20px" }}
                >
                  Enviar Comentário
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// Funções auxiliares
function formatAreaName(area) {
  return area.replace(/_/g, " ");
}

function getAreaIcon(area) {
  const icons = {
    Ciências_da_Computação: <MdComputer size={24} />,
    Contabilidade_Economia_e_Gestão: <MdAccountBalance size={24} />,
    Engenharia_de_Computadores: <MdEngineering size={24} />,
    Matemática: <MdCalculate size={24} />,
    Sistemas_de_Informação: <MdComputer size={24} />,
    Línguas_Estrangeiras: <FaLanguage size={24} />,
  };
  return icons[area] || <FaGraduationCap size={24} />;
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
